const crypto = require('crypto');

// Parse the output of the llm
const raw = ($json.text || '').replace(/```json|```/gi, '').trim();

const llmCards = JSON.parse(raw);

const card = Array.isArray(llmCards) ? llmCards[0] : llmCards;

const payload = {
  deck: card.deck,
  front: card.front,
  back: card.back,
};



// 1. Shared secret from n8n environment or credentials
const secret = $env.WEBHOOK_SECRET || 'my-secret-key';

// 2. Fresh Unix timestamp (in seconds)
const timestamp = Math.floor(Date.now() / 1000).toString();


// Serialize to a fixed string
const rawBody = JSON.stringify(payload);

// 4. Combine timestamp + payload and hash with SHA-256
const stringToSign = `${timestamp}.${rawBody}`;
const signature = crypto
  .createHmac('sha256', secret)
  .update(stringToSign)
  .digest('hex');

// Pass down to the next node
return {
  json: {
    rawBody,
    timestamp,
    signature,
  },
};
